mapper.select:
SELECT CASE WHEN iaad.access_label = 'LEIT_empty' THEN null ELSE iaad.access_label END as accessLabel, CASE WHEN iaad.system_role_type = 'LEIT_empty' THEN null ELSE iaad.system_role_type END as systemRoleType, CASE WHEN mgr.management_level IN ('Executive Director') THEN '2' WHEN mgr.management_level IN ('Vice President') THEN '3' WHEN mgr.management_level IN ('Senior Vice President', 'Executive Vice President', 'Chief Executive Officer') THEN '4' ELSE '1' END as lineManagerLevelCode,
FROM its_application_access_data as iaad LEFT JOIN ad_tb_upp_nature_2 staff ON iaad.user_it_code = staff.user_name LEFT JOIN ad_tb_upp_nature_2 mgr ON iaad.line_manager = mgr.user_name
ORDER BY ${request.sortField} ${request.sortOrder}
